package win.vampyuyu.survival.dungeon;

import win.vampyuyu.survival.api.DungeonApi;
import win.vampyuyu.survival.core.Core;
import win.vampyuyu.survival.core.Feature;
import win.vampyuyu.survival.dungeon.run.RunListener;
import win.vampyuyu.survival.dungeon.run.RunManager;

/**
 * Instanced procedural dungeons ("Catacombs") for parties. Runs live in {@code sb_dungeon_<n>} void worlds that are
 * generated by code, played, then unloaded and deleted. See docs/skyblock-notes/dungeon.md.
 */
public final class DungeonFeature implements Feature {
    private DungeonService service;

    @Override
    public String id() {
        return "dungeon";
    }

    @Override
    public void enable(Core core) {
        enable(core, RunManager.voidFactory());
    }

    /** Test entry point: a fake world factory keeps the unit tests away from real world creation. */
    public void enable(Core core, RunManager.WorldFactory worlds) {
        DungeonConfig cfg = DungeonConfig.parse(core.featureConfig("dungeon"));
        cfg.problems().forEach(p -> core.getPlugin().getLogger().warning("dungeon.yml: " + p));
        DungeonItems.register(core);
        core.permissions().register(RunListener.ADMIN, "Dungeon administration", org.bukkit.permissions.PermissionDefault.OP);
        service = new DungeonService(core, cfg, worlds);
        core.listen(new RunListener(service.ctx, service.runs));
        core.listen(new PartyListener(service));
        new PartyCommand(service).register();
        service.command = new DungeonCommand(service);
        service.command.register();
        service.runs.cleanOrphans();
        EntranceHint hint = new EntranceHint(service);
        core.scheduler().repeating(20, 20, () -> {
            service.parties.tick();
            hint.tick();
        });
        core.register(DungeonApi.class, new DungeonApiImpl());
    }

    @Override
    public void disable() {
        if (service != null) {
            service.runs.shutdown();
            service.parties.clear();
            service = null;
        }
    }

    /** The wired service (tests, other classes of the feature). */
    public DungeonService service() { return service; }
}
